but if add guard(`GRPC_HAVE_VSOCK`) here, then we should add guard when calling the functions: `grpc_resolve_vsock_address`, `grpc_is_vsock`. So I just added guard in vsock.cc, please review https://github.com/grpc/grpc/pull/32847/commits/219af457725a8d319a4188c331773b0768bb1cf3#diff-c66e654324529cd87a1924294674c2e49cbd82b939c46e4d5c2772ce98eb8a71
```
#ifdef GRPC_HAVE_VSOCK
void grpc_create_socketpair_if_vsock(int sv[2]) {
  GPR_ASSERT(socketpair(AF_VSOCK, SOCK_STREAM, 0, sv) == 0);
}
absl::StatusOr<std::vector<grpc_resolved_address>> grpc_resolve_vsock_address(
    absl::string_view name) {
  grpc_resolved_address addr;
  grpc_error_handle error = grpc_core::VSockaddrPopulate(name, &addr);
  GRPC_RETURN_IF_ERROR(error);
  return std::vector<grpc_resolved_address>({addr});
}
int grpc_is_vsock(const grpc_resolved_address* resolved_addr) {
  const grpc_sockaddr* addr =
      reinterpret_cast<const grpc_sockaddr*>(resolved_addr->addr);
  return addr->sa_family == AF_VSOCK;
}
#else
absl::StatusOr<std::vector<grpc_resolved_address>> grpc_resolve_vsock_address(
    absl::string_view /*name*/) {
  return absl::InvalidArgumentError("VSOCK is not supported.");
}

int grpc_is_vsock(const grpc_resolved_address* /*resolved_addr*/) {
  return 0;
}
#endif
